package org.usbworkbench;
import java.io.*;import java.util.*;
public final class DeepCapacityTest{
 static int checks;static void yes(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static class Disk implements BlockDevice{byte[] data=new byte[65536];int writes,reads,syncs;boolean wrap,corrupt;List<byte[]> seeds=new ArrayList<>();public int blockSize(){return 512;}public long blockCount(){return 128;}public void write(long at,byte[] b,int n){writes++;int offset=(int)at*512;if(wrap)offset%=32768;System.arraycopy(b,0,data,offset,n);}public void read(long at,byte[] b,int n){reads++;int offset=(int)at*512;if(wrap)offset%=32768;System.arraycopy(data,offset,b,0,n);if(corrupt&&syncs==2)b[0]^=1;}public void sync(){syncs++;seeds.add(Arrays.copyOf(data,512));}public void close(){}}
 public static void main(String[] args)throws Exception{Disk d=new Disk();long[] finalProgress={0,0};AdvancedDiskTools.capacityTest(d,3,(a,b)->{finalProgress[0]=a;finalProgress[1]=b;});yes(d.syncs==3,"all passes finish");yes(d.writes==12&&d.reads==12,"complete reads/writes per pass");yes(!Arrays.equals(d.seeds.get(0),d.seeds.get(1))&&!Arrays.equals(d.seeds.get(1),d.seeds.get(2)),"fresh patterns");yes(finalProgress[0]==393216&&finalProgress[1]==393216,"honest combined progress");
 d=new Disk();d.corrupt=true;try{AdvancedDiskTools.capacityTest(d,3,(a,b)->{});throw new AssertionError();}catch(IOException e){yes(e.getMessage().contains("CAPACITY_MISMATCH")&&e.getMessage().contains("pass=2"),"late-pass corruption detected");}yes(d.syncs==2,"no retry after corruption");
 d=new Disk();d.wrap=true;try{AdvancedDiskTools.capacityTest(d,3,(a,b)->{});throw new AssertionError();}catch(IOException e){yes(e.getMessage().startsWith("CAPACITY_MISMATCH"),"wrapped fake capacity rejected");}
 d=new Disk();try{AdvancedDiskTools.capacityTest(d,3,(a,b)->{if(a>=65536)throw new IOException("CANCELLED");});throw new AssertionError();}catch(IOException e){yes(e.getMessage().equals("CANCELLED"),"cancel propagates");}yes(d.syncs==1&&d.reads==0,"cancel stops before next work");
 d=new Disk();try{AdvancedDiskTools.capacityTest(d,2,(a,b)->{});throw new AssertionError();}catch(IOException e){yes(e.getMessage().equals("CAPACITY_OPTIONS"),"invalid pass count");}yes(d.writes==0,"invalid options never write");System.out.println("PASS: "+checks+" extended capacity full-pass/unique-pattern/fake-wrap/later-corruption/cancel/no-retry/no-write checks");}}
